    Bug 2042257 - End active OAuth requests when Thunderbird quits. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D302423

diff --git a/mailnews/base/src/OAuth2.sys.mjs b/mailnews/base/src/OAuth2.sys.mjs
index a3c45626946..3f31dcce820 100644
--- a/mailnews/base/src/OAuth2.sys.mjs
+++ b/mailnews/base/src/OAuth2.sys.mjs
@@ -281,6 +281,7 @@ OAuth2.prototype = {
       this.request.redirectURI
     );

+    Services.obs.addObserver(this, "quit-application-granted");
     if (!this.request.start(authEndpointURL)) {
       this.finishAuthorizationRequest();
       // Only the ExternalRequest construction is fallible here.
@@ -293,6 +294,7 @@ OAuth2.prototype = {
   },
   finishAuthorizationRequest() {
     gConnecting.set(this.authorizationEndpoint, false);
+    Services.obs.removeObserver(this, "quit-application-granted");
     if (this.request) {
       this.request.close();
       this.request = null;
@@ -504,6 +506,18 @@ OAuth2.prototype = {
       delete this.telemetryData.reason;
     }
   },
+
+  /**
+   * Fired on quit-application-granted to tidy up open requests.
+   */
+  observe() {
+    this.finishAuthorizationRequest();
+    this.onAuthorizationFailed(
+      Cr.NS_ERROR_ABORT,
+      '{ "error": "application_closed" }',
+      "application closed"
+    );
+  },
 };

